import ast
def score(program):
    """Counts nodes and names."""
    try:
        nodes = list(ast.walk(ast.parse(program)))
    except Exception:
        return 0.03
    names = {n.id for n in nodes if isinstance(n, ast.Name)}
    return min(1.0, len(nodes) / 320 + len(names) / 70)

